diff --git a/js/common/reviewVerdicts.js b/js/common/reviewVerdicts.js
index 9dbd6970..165a041f 100644
--- a/js/common/reviewVerdicts.js
+++ b/js/common/reviewVerdicts.js
@@ -91,13 +91,10 @@ function buildVerdictComment(record, provider) {
         at: record.at || new Date().toISOString(),
         source: record.source || 'pr_review.json'
     };
-    // The machine-readable marker (first line) is the only thing the SM parses. The sentence below it is only for
-    // a human who opens the PR: GitHub keeps the original text, other SCMs (Azure DevOps) get a neutral one without
-    // the internal gh-807 / SM-tick wording (agents#881).
-    var note = String(provider || '').toLowerCase() === 'ado' || String(provider || '').toLowerCase() === 'azure'
-        ? '🤖 Automated review record. Please do not edit or reply.'
-        : '🤖 Review verdict record (gh-807) — machine-parsed by the SM tick to ' +
-          'reconcile contradictory review legs on one head. Do not edit or reply.';
+    // The machine-readable marker (first line) is the only thing the SM parses. The sentence below is only for a
+    // human who opens the PR. It is provider-independent and carries no internal wording (gh-807 / SM tick):
+    // the SCM provider cannot be told reliably from config (ADO repos are often detected from the git remote).
+    var note = '\uD83E\uDD16 Automated review record. Please do not edit or reply.';
     return MARKER_PREFIX + JSON.stringify(payload) + MARKER_SUFFIX + '\n' + note;
 }

diff --git a/js/unit-tests/test_reviewVerdicts.js b/js/unit-tests/test_reviewVerdicts.js
index 2777ebf0..8784750e 100644
--- a/js/unit-tests/test_reviewVerdicts.js
+++ b/js/unit-tests/test_reviewVerdicts.js
@@ -41,19 +41,14 @@ suite('reviewVerdicts — marker protocol (gh-807 AC4)', function () {
         assert.contains(body, '"source":"pr_review.json"');
     });

-    test('GitHub keeps the explanatory sentence; Azure DevOps gets a neutral one without gh-807 / SM-tick wording (agents#881)', function () {
+    test('the human sentence is neutral for every provider: no gh-807 / SM-tick wording (agents#881)', function () {
         var rec = { head: 'abc123', verdict: 'APPROVE', at: '2026-10-09T05:47:30.000Z' };
-        var gh = rv.buildVerdictComment(rec);
-        assert.contains(gh, 'Review verdict record (gh-807)');
-        assert.contains(gh, 'machine-parsed by the SM tick');
-        ['ado', 'ADO', 'azure'].forEach(function (p) {
-            var ado = rv.buildVerdictComment(rec, p);
-            assert.equal(ado.indexOf('gh-807'), -1, 'provider=' + p);
-            assert.equal(ado.indexOf('SM tick'), -1, 'provider=' + p);
-            assert.contains(ado, 'Automated review record');
+        [undefined, 'github', 'gitlab', 'ado', 'azure'].forEach(function (p) {
+            var body = rv.buildVerdictComment(rec, p);
+            assert.equal(body.indexOf('gh-807'), -1, 'provider=' + p);
+            assert.equal(body.indexOf('SM tick'), -1, 'provider=' + p);
+            assert.contains(body, 'Automated review record');
         });
-        assert.equal(rv.buildVerdictComment(rec, 'github'), gh, 'github text is unchanged');
-        assert.equal(rv.buildVerdictComment(rec, undefined), gh, 'no provider = the old text');
     });

     test('the machine marker is identical for every provider and still parses (the SM only reads the marker)', function () {

{
  "key": "pr-891",
  "fields": {
    "summary": "fix(review): neutral verdict-record sentence for every provider (#881)",
    "description": "Fixes #881. #887 chose the neutral text by config.scm.provider, but ADO runs often leave it unset (repo detected from the git remote), so ADO PRs still got the gh-807 / SM-tick text. The sentence is now provider-independent; the machine marker is untouched. Tests updated."
  }
}

