        assert.notOk(rv.extractVerdictRecord('<!-- dmtools:review-verdict {"head":"h","verdict":"MAYBE"} -->'));
        assert.notOk(rv.extractVerdictRecord('<!-- dmtools:review-verdict {"head":"h","verdict":"APPROVE"}'));
